/**
 * One chat history entry (newest first from `chat_log`).
 */
public struct ChatMessage {
    public var id: String
    public var scope: String
    public var sender: String
    public var at: String
    public var receivedAt: String
    public var body: String
    public var blobHash: String?
    public var blobName: String?
    public var outgoing: Bool
    /**
     * `_outbox` delivery status of an outgoing message, when known.
     */
    public var status: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: String, scope: String, sender: String, at: String, receivedAt: String, body: String, blobHash: String?, blobName: String?, outgoing: Bool, 
        /**
         * `_outbox` delivery status of an outgoing message, when known.
         */status: String?) {
        self.id = id
        self.scope = scope
        self.sender = sender
        self.at = at
        self.receivedAt = receivedAt
        self.body = body
        self.blobHash = blobHash
        self.blobName = blobName
        self.outgoing = outgoing
        self.status = status
    }
}



extension ChatMessage: Equatable, Hashable {
    public static func ==(lhs: ChatMessage, rhs: ChatMessage) -> Bool {
        if lhs.id != rhs.id {
            return false
        }
        if lhs.scope != rhs.scope {
            return false
        }
        if lhs.sender != rhs.sender {
            return false
        }
        if lhs.at != rhs.at {
            return false
        }
        if lhs.receivedAt != rhs.receivedAt {
            return false
        }
        if lhs.body != rhs.body {
            return false
        }
        if lhs.blobHash != rhs.blobHash {
            return false
        }
        if lhs.blobName != rhs.blobName {
            return false
        }
        if lhs.outgoing != rhs.outgoing {
            return false
        }
        if lhs.status != rhs.status {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(id)
        hasher.combine(scope)
        hasher.combine(sender)
        hasher.combine(at)
        hasher.combine(receivedAt)
        hasher.combine(body)
        hasher.combine(blobHash)
        hasher.combine(blobName)
        hasher.combine(outgoing)
        hasher.combine(status)
    }
}


