/**
 * A successful query/execute: rows plus the `rsntr:Done` trailer facts.
 * A sparql CONSTRUCT/DESCRIBE answers with `turtle` set and no rows.
 */
public struct QueryResult {
    public var columns: [String]
    public var rows: [FfiRow]
    public var rowCount: Int64?
    public var affectedRows: Int64?
    public var lastInsertRowid: Int64?
    public var truncated: Bool
    public var turtle: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(columns: [String], rows: [FfiRow], rowCount: Int64?, affectedRows: Int64?, lastInsertRowid: Int64?, truncated: Bool, turtle: String?) {
        self.columns = columns
        self.rows = rows
        self.rowCount = rowCount
        self.affectedRows = affectedRows
        self.lastInsertRowid = lastInsertRowid
        self.truncated = truncated
        self.turtle = turtle
    }
}



extension QueryResult: Equatable, Hashable {
    public static func ==(lhs: QueryResult, rhs: QueryResult) -> Bool {
        if lhs.columns != rhs.columns {
            return false
        }
        if lhs.rows != rhs.rows {
            return false
        }
        if lhs.rowCount != rhs.rowCount {
            return false
        }
        if lhs.affectedRows != rhs.affectedRows {
            return false
        }
        if lhs.lastInsertRowid != rhs.lastInsertRowid {
            return false
        }
        if lhs.truncated != rhs.truncated {
            return false
        }
        if lhs.turtle != rhs.turtle {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(columns)
        hasher.combine(rows)
        hasher.combine(rowCount)
        hasher.combine(affectedRows)
        hasher.combine(lastInsertRowid)
        hasher.combine(truncated)
        hasher.combine(turtle)
    }
}


