/**
 * The receipt of a `chat_send`: the send is an `_outbox` enqueue;
 * delivery happens while the node serves.
 */
public struct SendReceipt {
    public var messageId: String
    public var scope: String
    public var queuedTo: [String]
    public var blobHash: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(messageId: String, scope: String, queuedTo: [String], blobHash: String?) {
        self.messageId = messageId
        self.scope = scope
        self.queuedTo = queuedTo
        self.blobHash = blobHash
    }
}



extension SendReceipt: Equatable, Hashable {
    public static func ==(lhs: SendReceipt, rhs: SendReceipt) -> Bool {
        if lhs.messageId != rhs.messageId {
            return false
        }
        if lhs.scope != rhs.scope {
            return false
        }
        if lhs.queuedTo != rhs.queuedTo {
            return false
        }
        if lhs.blobHash != rhs.blobHash {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(messageId)
        hasher.combine(scope)
        hasher.combine(queuedTo)
        hasher.combine(blobHash)
    }
}


