public enum FfiError {

    
    
    /**
     * Connection, engine, protocol, or local failure.
     */
    case Failure(msg: String
    )
    /**
     * The serving side's authenticator or policy said no.
     */
    case Denied(reason: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiError: FfiConverterRustBuffer {
    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Failure(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Denied(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Failure(msg):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Denied(reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


extension FfiError: Equatable, Hashable {}

extension FfiError: Foundation.LocalizedError {
    public var errorDescription: String? {
        String(reflecting: self)
    }
}

// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * One envelope value crossing the FFI. `BlobRef` results (blobs beyond
 * the frame cap) arrive as `Text` carrying the `blake3:<hex>` hash.
 */

public enum FfiValue {
    
    case null
    case integer(v: Int64
    )
    case real(v: Double
    )
    case text(v: String
    )
    case blob(v: Data
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiValue: FfiConverterRustBuffer {
    typealias SwiftType = FfiValue

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiValue {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .null
        
        case 2: return .integer(v: try FfiConverterInt64.read(from: &buf)
        )
        
        case 3: return .real(v: try FfiConverterDouble.read(from: &buf)
        )
        
        case 4: return .text(v: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .blob(v: try FfiConverterData.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiValue, into buf: inout [UInt8]) {
        switch value {
        
        
        case .null:
            writeInt(&buf, Int32(1))
        
        
        case let .integer(v):
            writeInt(&buf, Int32(2))
            FfiConverterInt64.write(v, into: &buf)
            
        
        case let .real(v):
            writeInt(&buf, Int32(3))
            FfiConverterDouble.write(v, into: &buf)
            
        
        case let .text(v):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(v, into: &buf)
            
        
        case let .blob(v):
            writeInt(&buf, Int32(5))
            FfiConverterData.write(v, into: &buf)
            
        }
    }
}


